BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats13-q01', 'モデル選択と正則化',
   '回帰分析で、直線1本(単純なモデル)から、なめらかにうねる9次曲線(複雑なモデル)まで、モデルの複雑さを少しずつ上げていく。訓練データへの当てはまりと、新しいデータでの予測は、複雑さを上げるほどそれぞれどうなる？',
   NULL::text,
   '["訓練データの誤差は下がり続けるが、新しいデータの誤差はある複雑さを境に上がり始める。", "訓練データの誤差はある複雑さを境に下がり止まるが、新しいデータの誤差は下がり続ける。", "訓練データの誤差も新しいデータの誤差も、複雑さを上げるほどそろって下がり続ける。", "訓練データの誤差も新しいデータの誤差も、複雑さを上げるほどそろって上がり続ける。"]',
   0, '[0]', 'single',
   '{"asked": "モデルの複雑さを上げていくと、訓練データへの当てはまりと新しいデータでの予測がそれぞれどう変わるか。", "point": "訓練誤差は複雑さを上げるほど下がり続けるが、新しいデータへの誤差はある複雑さを境に下げ止まり、むしろ上がり始める。", "kid": "モデルを複雑にすればするほど「今持っているデータ」にはどんどんぴったり合わせられる。でも合わせすぎると、そのデータだけの細かいクセ(ノイズ)まで覚えてしまい、初めて見るデータには逆に弱くなる。", "eg": "オーダーメイドの服に例えると分かりやすい。今日の体にぴったり合わせすぎたきつきつの服(複雑なモデル)は、今日は快適でも、少し体型が変わった翌日にはもう合わなくなる。少しゆとりのある服(適度な複雑さ)のほうが、長く着られる。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">複雑さを上げると誤差はどう動く？</text><line x1=\"30\" y1=\"112\" x2=\"310\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"308\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">複雑さ →</text><path d=\"M40,50 Q120,88 180,98 Q240,105 300,110\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/><path d=\"M40,88 Q110,52 175,58 Q240,72 300,32\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><line x1=\"178\" y1=\"34\" x2=\"178\" y2=\"112\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><text x=\"178\" y=\"30\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">ちょうどいい複雑さ</text><rect x=\"35\" y=\"128\" width=\"9\" height=\"9\" fill=\"#3b82f6\"/><text x=\"48\" y=\"136\" fill=\"#8892a4\" font-size=\"8.5\">訓練データの誤差(下がり続ける)</text><rect x=\"35\" y=\"140\" width=\"9\" height=\"9\" fill=\"#c9a04a\"/><text x=\"48\" y=\"148\" fill=\"#8892a4\" font-size=\"8.5\">新しいデータの誤差(U字に転じる)</text></svg>", "terms": [["訓練誤差", "訓練データそのものに対する予測の誤差"], ["過剰適合(過学習)", "訓練データを覚えすぎて新しいデータで崩れる状態。既に学んだ現象"]], "think": "なぜ複雑にするほど新しいデータの誤差がU字に転じるのかがカギ。モデルが複雑になるほど、訓練データに含まれる本来の傾向だけでなく、たまたま混ざったノイズの形までなぞれるようになる。訓練誤差はノイズごと覚え込むので下がり続ける。しかし新しいデータはそのノイズの形を持っていないので、ノイズまでなぞった複雑すぎるモデルはかえって外れやすくなる。だから新しいデータでの誤差は、ある複雑さまでは下がるが、そこを超えると上がりに転じる。", "vs": "「複雑=高性能」というイメージと違い、複雑さと新しいデータへの強さは比例しない。ちょうどよい複雑さを選ぶという発想が、この先のAIC・BIC・正則化・交差検証すべての土台になる。", "why_asked": "「複雑なモデルほど賢い」という直感は訓練データの上でしか正しくない。この誤解を持ったまま先に進むと、AICやBIC、正則化が「なぜ複雑さにペナルティを科すのか」が腹落ちしなくなる。", "usecase": "回帰式の次数選び、決定木の深さ選び、ニューラルネットの層数選びなど、モデルの複雑さを自分で決める場面すべてで、この右下がり×U字の関係を思い出す。", "opt": ["正解。複雑にするほど訓練データにはより深く合わせ込めるので訓練誤差は下がり続ける。しかし合わせ込みすぎたぶんは新しいデータには通用せず、ある複雑さを境に新しいデータの誤差はむしろ上がり始める。", "訓練誤差が下げ止まる一方で新しいデータの誤差だけが下がり続けるのは逆。実際は訓練誤差のほうが下がり続け、新しいデータの誤差がある複雑さを境に上がり始める。", "訓練データの誤差はモデルを複雑にするほど実際に下がり続けるが、新しいデータの誤差はそろって下がり続けるわけではなく、ある複雑さを境に上がり始める。", "訓練データの誤差はモデルを複雑にするほど下がり続けるので、そろって上がり続けることはない。上がり続けるのは複雑さを上げすぎたときの新しいデータの誤差だけ。"]}'),

  ('stats13-q02', 'モデル選択と正則化',
   'モデルの予測のズレは大きく2種類に分けられる。1つは「単純すぎて、そもそも当てはまりが悪い」というズレ(バイアス)。もう1つは「複雑すぎて、訓練データが変わるたびに予測が大きく変わってしまう」というブレ(バリアンス)。単純な直線モデルと複雑な9次曲線モデルを比べたとき、正しい組み合わせはどれ？',
   NULL::text,
   '["単純なモデルはバイアスが大きく当てはまりが悪くなり、複雑なモデルはバリアンスが大きく予測が大きくブレる。", "複雑なモデルはバイアスが大きく当てはまりが悪くなり、単純なモデルはバリアンスが大きく予測が大きくブレる。", "単純なモデルも複雑なモデルも、バイアスとバリアンスはどちらも同じくらいの大きさになる。", "モデルを複雑にしていくと、バイアスとバリアンスはどちらも同時に小さくなっていく。"]',
   0, '[0]', 'single',
   '{"asked": "単純すぎるモデルと複雑すぎるモデルで、予測のズレの原因がバイアスとバリアンスのどちらに寄っているか。", "point": "単純すぎる→毎回同じようにズレる(バイアス大)。複雑すぎる→データが変わるたびに予測がブレる(バリアンス大)。", "kid": "バイアスは「的から一定方向にずれて当たり続けるクセ」、バリアンスは「毎回バラバラの場所に飛んでしまうブレ」。単純なモデルはクセが強く、複雑なモデルはブレが強い。", "eg": "弓矢の的当てで例えると分かりやすい。腕は固いが狙いが甘い人は、毎回的の同じ方向にずれた場所に矢が集まる(バイアス大・バラつきは小さい)。逆に狙いは正確だが手がぶれる人は、矢が的のあちこちに散らばる(バリアンス大)。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">的当てで見るバイアスとバリアンス</text><circle cx=\"85\" cy=\"68\" r=\"38\" fill=\"none\" stroke=\"#2a2f3f\"/><circle cx=\"85\" cy=\"68\" r=\"25\" fill=\"none\" stroke=\"#2a2f3f\"/><circle cx=\"85\" cy=\"68\" r=\"12\" fill=\"none\" stroke=\"#2a2f3f\"/><circle cx=\"108\" cy=\"51\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"112\" cy=\"56\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"105\" cy=\"57\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"110\" cy=\"48\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"255\" cy=\"68\" r=\"38\" fill=\"none\" stroke=\"#2a2f3f\"/><circle cx=\"255\" cy=\"68\" r=\"25\" fill=\"none\" stroke=\"#2a2f3f\"/><circle cx=\"255\" cy=\"68\" r=\"12\" fill=\"none\" stroke=\"#2a2f3f\"/><circle cx=\"255\" cy=\"47\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"276\" cy=\"82\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"234\" cy=\"87\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"263\" cy=\"95\" r=\"3\" fill=\"#60a5fa\"/><text x=\"85\" y=\"122\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">単純なモデル</text><text x=\"85\" y=\"135\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">バイアス大</text><text x=\"255\" y=\"122\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">複雑なモデル</text><text x=\"255\" y=\"135\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">バリアンス大</text></svg>", "terms": [["バイアス", "モデルが単純すぎて生じる、当てはまりの悪さ(一定方向のズレ)"], ["バリアンス", "モデルが複雑すぎて生じる、訓練データが変わるたびの予測の不安定さ(ブレ)"]], "think": "なぜ単純さと複雑さでズレの種類が違うのかがカギ。単純なモデル(直線1本)は表現力が乏しく、データの形が曲がっていてもまっすぐにしか引けない。だからどんな訓練データを使っても同じように的を外し続ける、これがバイアス。複雑なモデル(9次曲線)は表現力が高すぎて、訓練データの細かいノイズまで拾ってしまう。訓練データが少し変わるとノイズの形も変わるので、曲線の形も毎回大きく変わってしまう、これがバリアンス。", "vs": "「バイアスもバリアンスも複雑さを下げれば両方減る」わけではない。バイアスを減らす(複雑にする)とバリアンスが増え、バリアンスを減らす(単純にする)とバイアスが増える、というシーソーの関係にある。", "why_asked": "この後に出てくるAIC・BIC・正則化・交差検証は、すべて「バイアスとバリアンスのちょうどいいバランス点」を探すための道具。バイアスとバリアンスが何を指すか分からないと、これらの道具が何のためにあるのか分からなくなる。", "usecase": "モデルの複雑さ(回帰の次数、決定木の深さ、正則化の強さ)を決めるとき、「当てはまりが悪すぎないか(バイアス)」と「新しいデータでブレすぎないか(バリアンス)」の両方を見て調整する。", "opt": ["正解。単純なモデルは表現力が乏しく毎回同じ方向に外し続けるためバイアスが大きく、複雑なモデルはノイズまで拾ってしまい訓練データが変わるたびに予測が大きく変わるためバリアンスが大きい。", "バイアスとバリアンスの対応が入れ替わっている。表現力が乏しく毎回同じようにズレるのは単純なモデルのバイアス、データが変わるたびに予測が大きくブレるのは複雑なモデルのバリアンス。", "単純なモデルはバイアスが大きくバリアンスは小さい、複雑なモデルはバリアンスが大きくバイアスは小さいというように、複雑さによって寄る方向が変わる。同じ大きさにはならない。", "複雑さを上げるとバイアスは小さくなる代わりにバリアンスは大きくなる、というシーソーの関係にある。両方が同時に小さくなることはない。"]}'),

  ('stats13-q03', 'モデル選択と正則化',
   '2つの回帰モデルを比べる。モデル1は変数2個で、当てはまりの良さを表す対数尤度が-50。モデル2は変数6個で対数尤度が-48。AIC=(-2×対数尤度)+(2×変数の数)で計算し、値が小さい方を選ぶとき、どちらのモデルを選ぶ？',
   NULL::text,
   '["モデル1のAICは104、モデル2のAICは108で、小さいモデル1を選ぶ", "モデル1の対数尤度は-50、モデル2の対数尤度は-48で、0に近いモデル2を選ぶ", "モデル1のAICは108、モデル2のAICは120で、小さいモデル1を選ぶ", "モデル1のAICは-104、モデル2のAICは-108で、小さいモデル2を選ぶ"]',
   0, '[0]', 'single',
   '{"asked": "対数尤度と変数の数からAICを計算し、値が小さい方のモデルを選ぶ。", "point": "AIC＝(-2×対数尤度)＋(2×変数の数)。値が小さいほど良いモデルと判断する。", "kid": "AICは「モデルの当てはまりの悪さ」と「変数を使いすぎていないか」の両方をまとめて1つの数字にしたもの。この数字が小さいほど、バランスの良いモデルだといえる。", "eg": "料理のコンテストで例えると、味の点数(当てはまりの良さ)だけでなく、使った食材の数(変数の数)にも少し減点をつけて審査するようなもの。同じくらい美味しくても、食材を使いすぎた料理は減点され、シンプルな料理のほうが総合点で勝つことがある。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">AIC＝当てはまりの悪さ＋複雑さの罰</text><text x=\"30\" y=\"32\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">モデル1(変数2個)</text><rect x=\"30\" y=\"38\" width=\"227\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"257\" y=\"38\" width=\"9\" height=\"20\" fill=\"#c9a04a\"/><text x=\"278\" y=\"53\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"start\" font-weight=\"700\">104</text><text x=\"30\" y=\"77\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">モデル2(変数6個)</text><rect x=\"30\" y=\"83\" width=\"218\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"248\" y=\"83\" width=\"27\" height=\"20\" fill=\"#c9a04a\"/><text x=\"278\" y=\"98\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"start\" font-weight=\"700\">108</text><text x=\"170\" y=\"120\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">青=当てはまりの悪さ(-2×対数尤度)　黄=複雑さの罰(2×変数の数)</text><text x=\"170\" y=\"136\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">小さい方(モデル1)を選ぶ</text></svg>", "terms": [["AIC(赤池情報量規準)", "当てはまりの良さと変数の数のバランスを1つの数値で評価する指標。小さいほど良い"], ["対数尤度", "モデルがデータにどれだけよく当てはまっているかを表す値。0に近いほど当てはまりが良い"]], "calc": "モデル1  対数尤度-50・変数2個\nAIC = -2×(-50) + 2×2 = 100+4 = 104\n\nモデル2  対数尤度-48・変数6個\nAIC = -2×(-48) + 2×6 = 96+12 = 108\n\n104 < 108 → モデル1を選ぶ", "think": "なぜ対数尤度だけでなく変数の数まで足すのかがカギ。モデル2は対数尤度が-48とモデル1の-50よりわずかに良く、訓練データへの当てはまりはモデル2のほうが良い。しかしモデル2は変数が6個とモデル1の2個よりずっと多く、変数を増やすほど当てはまりは自動的に良くなりやすい(問1で見た「複雑にするほど訓練誤差は下がる」現象と同じ)。AICは「2×変数の数」というペナルティを足すことで、この「変数を増やしただけの見かけの改善」を割り引く。ペナルティを足した結果、AICはモデル1のほうが小さくなり、複雑さに見合う改善ではないと判断できる。", "vs": "対数尤度だけを比べると、変数の多いモデルほど有利に見えてしまう。AICは対数尤度に変数の数のペナルティを足すことで、この見かけの有利さを補正する。「対数尤度が良い方を選ぶ」と「AICが小さい方を選ぶ」は別の判断基準。", "why_asked": "問1・問2のトレードオフ(複雑さと誤差の関係、バイアスとバリアンス)に、初めて具体的な数字の物差しを与えるのがAIC。数式を丸暗記するのではなく、「対数尤度＋複雑さのペナルティ」という2つの部品でできていることを理解する。", "usecase": "回帰分析で「どの変数を入れるべきか」を決めるとき、いくつかの変数の組み合わせのAICを計算して比べ、一番小さいものを採用する、というモデル選びの実務で使う。", "opt": ["正解。モデル1のAICは-2×(-50)+2×2=104、モデル2のAICは-2×(-48)+2×6=108。104のほうが小さいのでモデル1を選ぶ。", "対数尤度は当てはまりの良さだけを表す値で、変数の数のペナルティが含まれていない。対数尤度だけで比べると、変数の多いモデルが有利に見えすぎてしまう。", "2×変数の数の部分を計算する際に値がずれている。正しくはモデル1のペナルティは2×2=4、モデル2のペナルティは2×6=12で、AICはそれぞれ104と108になる。", "-2×対数尤度の符号のつけ方が違う。正しくは-2×対数尤度はプラスの値(モデル1は100、モデル2は96)になり、そこにペナルティを足すとAICは104と108になる。"]}'),

  ('stats13-q04', 'モデル選択と正則化',
   'AICは複雑さのペナルティに「2×変数の数」を使う。BICは同じ役割のペナルティに「log(データ数)×変数の数」を使う。データが100件のとき、log(100)は2よりずっと大きい数になる。この違いから言えることはどれ？',
   NULL::text,
   '["データ数が多いほど、BICはAICよりも複雑なモデルを厳しく罰する", "データ数が多いほど、BICはAICよりも複雑なモデルに甘くなる", "データ数が多くても少なくても、BICとAICの罰の大きさは常に同じになる", "データ数が多いほど、AICの方がBICよりも複雑なモデルを厳しく罰するようになる"]',
   0, '[0]', 'single',
   '{"asked": "AICとBICはどちらも複雑さにペナルティを科す指標だが、データ数が増えたときにペナルティの大きさがどう変わるか。", "point": "AICのペナルティは常に「2×変数の数」で一定。BICのペナルティは「log(データ数)×変数の数」で、データが増えるほど大きくなる。", "kid": "AICは何件分のデータで計算しても、複雑さへの罰の重さは変わらない。BICはデータの件数が増えれば増えるほど、複雑さへの罰がどんどん重くなっていく。", "eg": "罰金のルールで例えると、AICは「違反1件につき常に2万円」という固定の罰金。BICは「町の人口が増えるほど、違反1件あたりの罰金も上がっていく」という罰金。人口(データ数)が多い町ほど、同じ違反でもBICのほうが重く罰する。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">データ数が増えるほどBICの罰は重くなる</text><line x1=\"30\" y1=\"115\" x2=\"310\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><rect x=\"52\" y=\"95\" width=\"18\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"72\" y=\"92\" width=\"18\" height=\"23\" fill=\"#c9a04a\"/><text x=\"70\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">n=10</text><rect x=\"152\" y=\"95\" width=\"18\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"172\" y=\"69\" width=\"18\" height=\"46\" fill=\"#c9a04a\"/><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">n=100</text><rect x=\"252\" y=\"95\" width=\"18\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"272\" y=\"46\" width=\"18\" height=\"69\" fill=\"#c9a04a\"/><text x=\"270\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">n=1000</text><text x=\"170\" y=\"142\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">青=AICの罰(常に2)　黄=BICの罰(log(n)、nが増えるほど伸びる)</text></svg>", "terms": [["BIC(ベイズ情報量規準)", "当てはまりの良さと複雑さのバランスを見る指標。AICよりデータ数が多いときに複雑なモデルを厳しく罰する"], ["log(データ数)", "データの件数から計算する、データが増えるほどゆっくり大きくなる数。ここでは自然対数(eを何回掛けたらその数になるかを表すlog。eは既に学んだネイピア数、約2.72)を使う。以前学んだlog₂(2を何回掛けたか)とは底が違う"]], "calc": "AICのペナルティ(1変数あたり)  常に 2\n\nBICのペナルティ(1変数あたり)  log(データ数)\nデータ数10件   log(10)  ≈ 2.3\nデータ数100件  log(100) ≈ 4.6\nデータ数1000件 log(1000)≈ 6.9\n\nデータが増えるほどBICのペナルティがAICの2を追い越して大きくなる", "think": "なぜデータ数が増えるとBICのペナルティだけが重くなるのかがカギ。AICのペナルティ(2×変数の数)はデータ数を含まない、いつも同じ重さの罰。一方BICのペナルティ(log(データ数)×変数の数)は、データ数が大きくなるほどlog(データ数)自体が大きくなるので、変数1個あたりの罰もそれにつれて重くなる。データが少ないうちはlog(データ数)は2前後でAICとほぼ同じだが、データが増えるとAICの固定の2を追い越して、より厳しい罰になっていく。", "vs": "「BICのほうがいつも複雑なモデルに厳しい」わけではない。データ数が少ないとき(だいたい8件未満)はむしろBICの罰のほうが軽くなる。BICが厳しくなるのは、データが多いとき、という条件つき。", "why_asked": "同じ「モデル選びの指標」でもAICとBICで結果が変わることがある。データが多い場面ではBICのほうがより単純なモデルを選びやすい、という違いを知らないと、どちらを使うべきか判断できない。", "usecase": "手元のデータの件数が多い分析ではBIC、少ないデータや予測精度そのものを重視したい分析ではAIC、というように使い分ける場面で登場する。", "opt": ["正解。BICのペナルティlog(データ数)×変数の数は、データ数が増えるほどlog(データ数)自体が大きくなり、常に2のままのAICのペナルティより重くなっていく。", "データが増えるほどlog(データ数)は大きくなる一方なので、BICのペナルティが軽くなることはない。データが増えるほどBICはむしろ複雑なモデルに厳しくなる。", "AICのペナルティは常に2で一定だが、BICのペナルティはlog(データ数)で変わる。データ数が変わればBICのペナルティも変わるので、常に同じ大きさにはならない。", "log(データ数)×変数の数はデータが増えるほど大きくなる側であり、常に2のままのAICのほうがデータ数が増えても厳しくなることはない。厳しくなるのはBICのほう。"]}'),

  ('stats13-q05', 'モデル選択と正則化',
   '回帰分析で、モデルの当てはまりの良さ(誤差の小ささ)だけを追い求めて係数を自由に調整すると、過剰適合(過学習)に陥りやすい。そこで、当てはまりの良さに加えて「係数の大きさへの罰」も一緒に小さくしようとする学習の工夫を何と呼ぶ？',
   NULL::text,
   '["正則化（当てはまりの良さに、係数の大きさへの罰を足す）", "交差検証（データの分け方を何通りも変えて、複数回テストする）", "標準化（データの単位をそろえて、平均0・標準偏差1に変換する）", "過剰適合（訓練データを覚えすぎて、新しいデータで崩れる現象）"]',
   0, '[0]', 'single',
   '{"asked": "当てはまりの良さだけでなく、係数の大きさへの罰も一緒に小さくする学習の工夫の名前。", "point": "正則化＝「誤差を減らせ」に加えて「係数を大きくしすぎるな」という罰を式に足して学習させること。", "kid": "普通の学習は「予測が外れないように係数を調整する」ことだけを目指す。正則化はそこに「係数をむやみに大きくしたら減点」というルールを追加してから学習させる工夫。", "eg": "引っ越しの荷造りで例えると、普通は「必要なものは全部持っていく」で終わる。正則化は「必要なものは持っていくけど、荷物が重くなるほど運搬料が高くなる」という追加ルールを最初から入れて荷造りさせるようなもの。結果、本当に必要なものだけ厳選される。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">正則化＝誤差 ＋ 係数への罰</text><rect x=\"30\" y=\"38\" width=\"110\" height=\"34\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"85\" y=\"59\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">誤差をなるべく小さく</text><text x=\"152\" y=\"59\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\">+</text><rect x=\"165\" y=\"38\" width=\"110\" height=\"34\" fill=\"#c9a04a\" opacity=\"0.55\"/><text x=\"220\" y=\"59\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\">係数の大きさへの罰</text><line x1=\"170\" y1=\"78\" x2=\"170\" y2=\"92\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"170,96 165,88 175,88\" fill=\"#8892a4\"/><rect x=\"75\" y=\"98\" width=\"190\" height=\"26\" fill=\"#6ab08d\" opacity=\"0.5\"/><text x=\"170\" y=\"115\" fill=\"#141720\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">両方を一緒に小さくする＝正則化</text></svg>", "terms": [["正則化", "当てはまりの良さに、係数の大きさへの罰(ペナルティ)を足して学習する工夫"], ["罰(ペナルティ)", "係数が大きくなるほど、学習の目的の値に上乗せされる、いわば減点"]], "think": "なぜ係数の大きさに罰を科すと過剰適合が防げるのかがカギ。過剰適合したモデルは、訓練データの細かいノイズにまで無理に合わせようとして、いくつかの係数がとても大きな値になりがち(ノイズに強く反応するほど、その変数の効き具合のつまみを目一杯回すことになる)。係数が大きくなるほど罰も大きくなるルールを入れておけば、モデルは「ノイズに合わせて係数を目一杯大きくする」ことを避けるようになり、結果として複雑になりすぎるのを防げる。", "vs": "交差検証は「学習し終えたモデルの性能を確かめる」ための方法。正則化は「学習そのもののルールを変える」工夫。目的も使うタイミングも別。", "why_asked": "この後に出てくるリッジ回帰・ラッソ回帰は、どちらも正則化という考え方の中の具体的な2つのやり方。まず「係数への罰を足す」という発想そのものを理解していないと、リッジとラッソの違いが単なる公式の暗記になってしまう。", "usecase": "変数の数が多い回帰分析で、係数が不自然に大きくなって新しいデータへの予測が不安定になるのを防ぎたいときに使う。", "opt": ["正解。誤差を減らすことに加えて、係数が大きくなるほど罰も大きくなるルールを足して学習させるのが正則化。", "交差検証はデータの分け方を何通りも変えて複数回テストし、性能を確かめる方法。学習のルールそのものを変える正則化とは別物。", "標準化はデータの単位をそろえる前処理で、正則化を使う前に済ませておくことが多い準備の工程。正則化そのものではない。", "過剰適合は係数への罰が無いために起きてしまう現象の名前であり、それを防ぐための工夫である正則化とは逆の立場にある。"]}'),

  ('stats13-q06', 'モデル選択と正則化',
   '正則化の1つで、係数を0に近づけて縮小するが、どんなに罰を強めても係数がちょうど0にはならない(小さくなるだけ)という性質を持つ方法を何と呼ぶ？',
   NULL::text,
   '["リッジ回帰（L2正則化。係数の2乗の大きさに罰を科し、0に近づけるが完全には0にしない）", "ラッソ回帰（L1正則化。係数の絶対値の大きさに罰を科し、一部を完全に0にできる）", "交差検証（データの分け方を何通りも変えて、複数回テストする）", "最小二乗法（誤差の2乗の合計が最小になるように係数を決める、正則化を使わない基本の方法）"]',
   0, '[0]', 'single',
   '{"asked": "係数を0に近づけるが完全には0にしない正則化の方法の名前。", "point": "リッジ回帰(L2正則化)は係数の2乗を罰にする。罰を強めるほど係数は0に近づくが、0ぴったりにはならず、僅かに残り続ける。", "kid": "リッジ回帰は「係数をなるべく小さく、控えめにしなさい」というルールを加えて学習する方法。ただし、どんなに控えめにさせても、係数をゼロにはさせない。", "eg": "ダイエットで例えると、リッジ回帰は「みんな少しずつ減量しなさい」というルール。全員が痩せて体重は軽くなるが、誰か1人を完全に0kgにする(退場させる)ことはない。全員が少しずつ小さくなって残り続ける。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">リッジ回帰：どの係数も少しずつ縮む(0にはならない)</text><text x=\"18\" y=\"36\" fill=\"#8892a4\" font-size=\"9\">x1</text><rect x=\"40\" y=\"27\" width=\"220\" height=\"9\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><rect x=\"40\" y=\"39\" width=\"141\" height=\"9\" fill=\"#3b82f6\"/><text x=\"265\" y=\"48\" fill=\"#8892a4\" font-size=\"8\">5.0→3.2</text><text x=\"18\" y=\"73\" fill=\"#8892a4\" font-size=\"9\">x2</text><rect x=\"40\" y=\"64\" width=\"132\" height=\"9\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><rect x=\"40\" y=\"76\" width=\"79\" height=\"9\" fill=\"#3b82f6\"/><text x=\"265\" y=\"85\" fill=\"#8892a4\" font-size=\"8\">3.0→1.8</text><text x=\"18\" y=\"110\" fill=\"#8892a4\" font-size=\"9\">x3</text><rect x=\"40\" y=\"101\" width=\"44\" height=\"9\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><rect x=\"40\" y=\"113\" width=\"18\" height=\"9\" fill=\"#3b82f6\"/><text x=\"265\" y=\"122\" fill=\"#8892a4\" font-size=\"8\">1.0→0.4</text><text x=\"170\" y=\"140\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">枠=元の係数(絶対値)　青=リッジ後の係数。全部0より大きいまま</text></svg>", "terms": [["リッジ回帰(L2正則化)", "係数の2乗の大きさに罰を科す正則化。係数を0に近づけるが完全には0にしない"], ["L2", "係数を2乗してから罰にする、というペナルティの付け方を表す呼び名"]], "think": "なぜ2乗の罰では係数がちょうど0にならないのかがカギ。係数の2乗を罰にすると、係数が小さくなるほど、その罰による「小さくしろ」という引っぱる力も一緒に弱まっていく(4を2乗すると16、2を2乗すると4のように、小さい数の2乗はもっと小さくなるため)。係数が0に近づけば近づくほど引っぱる力そのものがほぼ0になってしまうので、最後の一押しができず、係数はごくわずかに残ったところで止まる。", "vs": "「係数を小さくする」という点はラッソ回帰と共通だが、リッジは係数を0の手前で止め、ラッソは0まできっちり押し切れる。この違いは罰のかけ方(2乗か絶対値か)の違いから生まれる。", "why_asked": "この先の「リッジとラッソの使い分け」を理解するには、まずリッジが「縮小はするが変数を完全には削らない」方法だと知っておく必要がある。", "usecase": "使えそうな変数がたくさんあり、どれも少しずつ関係がありそうで無理に削りたくはないが、係数が大きくなりすぎるのは防ぎたい、というときに使う。", "opt": ["正解。係数の2乗を罰にするリッジ回帰(L2正則化)は、罰を強めるほど係数を0に近づけるが、0の手前で引っぱる力が弱まるため完全な0にはならない。", "ラッソ回帰(L1正則化)は係数の絶対値を罰にする方法で、こちらは効果の薄い係数をちょうど0にできる。0にはならず縮小するだけのリッジ回帰とは性質が逆。", "交差検証はデータの分け方を何通りも変えて性能を確かめる方法で、係数そのものを縮小する仕組みではない。目的が異なる。", "最小二乗法は誤差の2乗の合計を最小にするだけの、正則化を使わない基本の方法。係数への罰は無いため、係数を縮小する効果は持たない。"]}'),

  ('stats13-q07', 'モデル選択と正則化',
   '同じ正則化の仲間で、罰を強めていくと、一部の係数をちょうど0にできる(=その変数を実質使わない扱いにできる)方法を何と呼ぶ？',
   NULL::text,
   '["ラッソ回帰（L1正則化。係数の絶対値の大きさに罰を科し、一部を完全に0にできる）", "リッジ回帰（L2正則化。係数の2乗の大きさに罰を科し、0に近づけるが完全には0にしない）", "最小二乗法（誤差の2乗の合計が最小になるように係数を決める、正則化を使わない基本の方法）", "標準化（データの単位をそろえて、平均0・標準偏差1に変換する）"]',
   0, '[0]', 'single',
   '{"asked": "一部の係数をちょうど0にできる正則化の方法の名前。", "point": "ラッソ回帰(L1正則化)は係数の絶対値を罰にする。罰を強めるほど、効果の薄い変数の係数から順にちょうど0まで押し切られる。", "kid": "ラッソ回帰は「係数をなるべく小さく」というルールに加えて、「効果が薄いものは思いきってゼロにしてしまってよい」という削り方をする方法。", "eg": "引っ越しの断捨離で例えると、ラッソ回帰は「使っていないものは思いきって手放す」やり方。リッジ回帰が全員を少しずつ小さくするのに対し、ラッソ回帰は一部の荷物を「持っていかない(0個)」にまで減らす。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">ラッソ回帰：効果が薄い係数はちょうど0になる</text><text x=\"18\" y=\"36\" fill=\"#8892a4\" font-size=\"9\">x1</text><rect x=\"40\" y=\"27\" width=\"220\" height=\"9\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><rect x=\"40\" y=\"39\" width=\"154\" height=\"9\" fill=\"#3b82f6\"/><text x=\"265\" y=\"48\" fill=\"#8892a4\" font-size=\"8\">5.0→3.5</text><text x=\"18\" y=\"73\" fill=\"#8892a4\" font-size=\"9\">x2</text><rect x=\"40\" y=\"64\" width=\"88\" height=\"9\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><circle cx=\"44\" cy=\"81\" r=\"4\" fill=\"#c47070\"/><text x=\"265\" y=\"85\" fill=\"#8892a4\" font-size=\"8\">2.0→0(削除)</text><text x=\"18\" y=\"110\" fill=\"#8892a4\" font-size=\"9\">x3</text><rect x=\"40\" y=\"101\" width=\"26\" height=\"9\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><circle cx=\"44\" cy=\"118\" r=\"4\" fill=\"#c47070\"/><text x=\"265\" y=\"122\" fill=\"#8892a4\" font-size=\"8\">0.6→0(削除)</text><text x=\"170\" y=\"140\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">枠=元の係数(絶対値)　青=残った係数　赤丸=ちょうど0になった係数</text></svg>", "terms": [["ラッソ回帰(L1正則化)", "係数の絶対値の大きさに罰を科す正則化。効果の薄い係数を完全に0にできる"], ["L1", "係数の絶対値を罰にする、というペナルティの付け方を表す呼び名"]], "think": "なぜ絶対値の罰なら係数がちょうど0になるのかがカギ。絶対値を罰にすると、係数がどれだけ小さくなっても、罰による「小さくしろ」という引っぱる力の強さは変わらず一定のまま働き続ける(リッジのように係数が小さくなるほど力が弱まることがない)。係数がごくわずかでも残っていれば、一定の強さの力がそれを0まで押し切ってしまう。結果として、効果の薄い変数の係数はちょうど0になり、その変数は実質使われなくなる。", "vs": "リッジ回帰は「全部の変数を少しずつ残したまま縮小する」のに対し、ラッソ回帰は「不要な変数を完全に取り除く」効果を持つ。同じ正則化でも結果の形が違う。", "why_asked": "ラッソ回帰の「係数を0にできる」性質は、変数選択(使う変数を自動的に絞り込む)という実務上とても便利な効果につながる。この性質を知らないと、次の「リッジとラッソの使い分け」が判断できない。", "usecase": "変数の候補がたくさんあり、その中から本当に効いている変数だけを自動的に絞り込みたいとき(例えば100個の候補変数から重要な10個だけ残したいとき)に使う。", "opt": ["正解。係数の絶対値を罰にするラッソ回帰(L1正則化)は、引っぱる力が係数の大小によらず一定に働くため、効果の薄い係数を0まで押し切れる。", "リッジ回帰(L2正則化)は係数の2乗を罰にする方法で、こちらは係数を0に近づけるだけで完全には0にしない。一部をちょうど0にできるラッソ回帰とは性質が逆。", "最小二乗法は誤差の2乗の合計を最小にするだけの、正則化を使わない基本の方法。係数への罰が無いため、係数を0にする効果は持たない。", "標準化はデータの単位をそろえる前処理で、正則化を使う前に済ませておくことが多い準備の工程。係数を0にする効果そのものではない。"]}'),

  ('stats13-q08', 'モデル選択と正則化',
   '手元に20個の候補変数があり、どれも少しは関係がありそうで削りたくない場合と、20個のうちどれが本当に重要かを絞り込みたい場合とで、リッジ回帰とラッソ回帰をどう使い分けるべき？',
   NULL::text,
   '["削りたくないなら係数を縮小するだけのリッジ回帰、絞り込みたいなら係数を0にできるラッソ回帰を使う", "削りたくないなら係数を0にできるラッソ回帰、絞り込みたいなら係数を縮小するだけのリッジ回帰を使う", "どちらの目的でも、常にリッジ回帰の方が優れているのでリッジ回帰を使う", "どちらの目的でも、常にラッソ回帰の方が優れているのでラッソ回帰を使う"]',
   0, '[0]', 'single',
   '{"asked": "変数を削りたくない場合と、絞り込みたい場合で、リッジとラッソのどちらを選ぶべきか。", "point": "「縮小したいだけ」ならリッジ回帰、「不要な変数を削りたい」ならラッソ回帰。", "kid": "全部の変数を残したまま、それぞれを控えめにしたいときはリッジ回帰。逆に、いらない変数をはっきり取り除いて、本当に大事な変数だけ残したいときはラッソ回帰。", "eg": "部活のメンバーで例えると、リッジ回帰は「全員試合に出すけど、出場時間はみんな少しずつ短くする」やり方。ラッソ回帰は「実力が足りない一部の部員は、今回はベンチに置く(出場時間0)」やり方。どちらにするかは、全員残したいか絞り込みたいかで決める。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">残したいならリッジ、絞りたいならラッソ</text><text x=\"85\" y=\"32\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">リッジ回帰(残す)</text><rect x=\"40\" y=\"42\" width=\"12\" height=\"30\" fill=\"#3b82f6\"/><rect x=\"58\" y=\"52\" width=\"12\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"76\" y=\"60\" width=\"12\" height=\"12\" fill=\"#3b82f6\"/><rect x=\"94\" y=\"66\" width=\"12\" height=\"6\" fill=\"#3b82f6\"/><text x=\"85\" y=\"90\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">4変数とも0より大きいまま残る</text><line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"110\" stroke=\"#2a2f3f\"/><text x=\"255\" y=\"32\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">ラッソ回帰(絞る)</text><rect x=\"210\" y=\"42\" width=\"12\" height=\"30\" fill=\"#3b82f6\"/><rect x=\"228\" y=\"52\" width=\"12\" height=\"20\" fill=\"#3b82f6\"/><circle cx=\"252\" cy=\"70\" r=\"4\" fill=\"#c47070\"/><circle cx=\"270\" cy=\"70\" r=\"4\" fill=\"#c47070\"/><text x=\"255\" y=\"90\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">2変数がちょうど0になり消える</text><text x=\"170\" y=\"124\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">目的(残すか絞るか)で選ぶ方法を変える</text></svg>", "terms": [["リッジ回帰", "係数を0に近づけるが完全には0にしない。変数を残したまま縮小したいときに使う"], ["ラッソ回帰", "係数の一部をちょうど0にできる。不要な変数を削りたいときに使う"]], "think": "なぜ目的によって選ぶ方法が変わるのかがカギ。手元の変数がどれも少しずつ本当に関係していそうなら、変数を削ってしまうと大事な情報を失うおそれがある。この場合は、全部残しつつ大きくなりすぎないようにするリッジ回帰が向く。逆に、変数の候補が多すぎて本当に効いているものだけに絞り込みたいなら、効果の薄い変数の係数をちょうど0にして実質取り除いてくれるラッソ回帰が向く。「縮小だけしたいか、削りたいか」という目的の違いが、そのままリッジとラッソの選び方に対応する。", "vs": "「どちらが優れているか」という優劣の関係ではない。どちらも同じ正則化の仲間で、目的(残したいか削りたいか)によって向き不向きが分かれるだけ。", "why_asked": "リッジとラッソの数式の違い(2乗か絶対値か)だけを暗記していても、実務でどちらを選べばいいかは別問題。目的に応じた使い分けまで理解して初めて実務で使える知識になる。", "usecase": "候補変数が数千個ある分析ではラッソ回帰で絞り込み、逆に少数の重要そうな変数を全部使いたい分析ではリッジ回帰、というように実務で使い分ける。", "opt": ["正解。変数を削りたくないなら係数を縮小するだけで0にはしないリッジ回帰、不要な変数を絞り込みたいなら係数を0にできるラッソ回帰を使う。", "リッジ回帰とラッソ回帰の性質が入れ替わっている。係数を0にできるのはラッソ回帰、0にせず縮小するだけなのはリッジ回帰。対応が逆になっている。", "リッジ回帰は変数を残したまま縮小したいときに向く方法であり、変数を絞り込みたい場合には係数を0にできるラッソ回帰のほうが向いている。常にリッジ回帰が優れているわけではない。", "ラッソ回帰は不要な変数を削りたいときに向く方法であり、変数を残したまま縮小したい場合には0にしないリッジ回帰のほうが向いている。常にラッソ回帰が優れているわけではない。"]}'),

  ('stats13-q09', 'モデル選択と正則化',
   '20人分のデータでk=5の交差検証を行う。20人を4人ずつ5組(組1〜組5)に分けたあと、正しい手順はどれ？',
   NULL::text,
   '["組1を検証用、残り4組を訓練用にして評価。組を入れ替えながら5回繰り返し平均する", "組1〜組5をすべて訓練用にし、新しく用意した別のデータを検証用にして1回だけ評価する", "組1だけを訓練用にし、組2〜組5をまとめて検証用にして1回だけ評価する", "毎回1人だけをランダムに検証用に選び、これを20回繰り返して平均する"]',
   0, '[0]', 'single',
   '{"asked": "k=5の交差検証で、20人分のデータをどういう順番で訓練用・検証用に割り振っていくかという具体的な手順。", "point": "5つの組それぞれを1回ずつ検証用に回し、残り4組を訓練用にして、5回分の評価を平均する。", "kid": "クラスを5つの班に分けて、毎回1つの班だけ「今回の答え合わせ係」にして、残りの班で練習してからその答え合わせ係でテストする。これを5回、班を入れ替えながら繰り返して、5回分の点数を平均する。", "eg": "野球でいうと、5人のピッチャーを順番に先発させて、それ以外の4人は毎回サポートに回るのと似ている。全員が1回は先発(検証用)を経験し、それ以外の回はサポート(訓練用)に回る。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">k=5交差検証：検証役の組が1つずつ移動する</text><text x=\"78\" y=\"25\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">組1</text><text x=\"124\" y=\"25\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">組2</text><text x=\"170\" y=\"25\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">組3</text><text x=\"216\" y=\"25\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">組4</text><text x=\"262\" y=\"25\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">組5</text><text x=\"45\" y=\"41\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">1巡目</text><rect x=\"56\" y=\"32\" width=\"44\" height=\"14\" fill=\"#c9a04a\"/><rect x=\"102\" y=\"32\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"148\" y=\"32\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"194\" y=\"32\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"240\" y=\"32\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"45\" y=\"59\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">2巡目</text><rect x=\"56\" y=\"50\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"102\" y=\"50\" width=\"44\" height=\"14\" fill=\"#c9a04a\"/><rect x=\"148\" y=\"50\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"194\" y=\"50\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"240\" y=\"50\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"45\" y=\"77\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">3巡目</text><rect x=\"56\" y=\"68\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"102\" y=\"68\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"148\" y=\"68\" width=\"44\" height=\"14\" fill=\"#c9a04a\"/><rect x=\"194\" y=\"68\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"240\" y=\"68\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"45\" y=\"95\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">4巡目</text><rect x=\"56\" y=\"86\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"102\" y=\"86\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"148\" y=\"86\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"194\" y=\"86\" width=\"44\" height=\"14\" fill=\"#c9a04a\"/><rect x=\"240\" y=\"86\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"45\" y=\"113\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">5巡目</text><rect x=\"56\" y=\"104\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"102\" y=\"104\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"148\" y=\"104\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"194\" y=\"104\" width=\"44\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"240\" y=\"104\" width=\"44\" height=\"14\" fill=\"#c9a04a\"/><text x=\"170\" y=\"133\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">黄=その回の検証用(4人)　灰=訓練用(16人)</text><text x=\"170\" y=\"146\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">5回分の評価を平均してスコアにする</text></svg>", "terms": [["k分割交差検証", "データをk個の組に分け、1組ずつ順番に検証用にして、残りを訓練用にする、をk回繰り返す方法"], ["フォールド(組)", "交差検証でデータを分けた、それぞれのかたまり"]], "calc": "組       組1  組2  組3  組4  組5\n\n1巡目: 組1=検証(4人) 組2〜5=訓練(16人) → 評価1\n2巡目: 組2=検証(4人) 組1,3〜5=訓練(16人) → 評価2\n3巡目: 組3=検証(4人) 組1,2,4,5=訓練(16人) → 評価3\n4巡目: 組4=検証(4人) 組1〜3,5=訓練(16人) → 評価4\n5巡目: 組5=検証(4人) 組1〜4=訓練(16人) → 評価5\n\n最終スコア = (評価1+評価2+評価3+評価4+評価5) ÷ 5", "think": "なぜ1回の分割だけでなく、5回すべての組を検証用に回すのかがカギ。もし組1だけを検証用に固定してしまうと、その組1がたまたま簡単(または難しい)だっただけで、実力を見誤るおそれがある(問1で見た「たまたま」の話と同じ構造)。5つの組それぞれに検証役を1回ずつ経験させれば、20人全員がちょうど1回は検証用として使われることになり、たまたまの当たり外れを5回分の平均でならせる。だから「順番に入れ替えながら5回繰り返す」という手順そのものが、信頼できる評価を得るためのしくみになっている。", "vs": "「1回だけ分けて評価する」方法(ホールドアウト法)と違い、交差検証は同じデータをk回、役割を入れ替えながら使い切る。1人1人が必ず1回は検証用になる点が特徴。「1人だけを検証用にして20回繰り返す」やり方は、k=20にした場合(1人抜き交差検証)にあたる別の手法で、今回のk=5とは分け方の粒度が違う。", "why_asked": "交差検証という名前と「何度も試す」というざっくりした理解だけでは、実際に何を何回、どう入れ替えるのかを問われると答えられない。この具体的な手順まで分かって初めて、次のグリッドサーチ(交差検証を土台にした方法)が理解できる。", "usecase": "正則化の強さのようなハイパーパラメータをいくつか試して、どれが一番良いかを比べたいとき、それぞれの候補についてk分割交差検証で平均スコアを出して比較する。", "opt": ["正解。組1を検証用・残り4組を訓練用にして評価し、次は組2を検証用にして評価、というように組を入れ替えながら5回繰り返し、5回分の評価を平均する。", "全部の組を訓練用にしてしまうと検証用のデータが残らず、性能を確かめられない。交差検証は手元のデータの一部を必ず検証用として取り分ける。", "組1だけを訓練用にすると学習に使えるデータがわずか4人分しかなく、残り16人を検証だけに使うのはデータの割り振りが逆で、しかも1回しか評価していない。", "1人だけを検証用にする分け方はk=20(1人抜き交差検証)という別の手法にあたり、今回のk=5(4人ずつ5組)の手順とは分け方の粒度が異なる。"]}'),

  ('stats13-q10', 'モデル選択と正則化',
   '正則化の強さλの候補が0.1・1・10の3通り、変数を絞る度合いαの候補が0.5・1の2通りある。この2つを組み合わせてすべて交差検証で試すグリッドサーチでは、何通りの組み合わせを試すことになる？',
   NULL::text,
   '["6通り（3×2をすべて試す）", "5通り（3+2を試す）", "3通り（λの候補だけを試す）", "2通り（αの候補だけを試す）"]',
   0, '[0]', 'single',
   '{"asked": "グリッドサーチで、複数のハイパーパラメータの候補を組み合わせて総当たりするとき、何通り試すことになるか。", "point": "グリッドサーチは候補の数どうしを掛け算した、すべての組み合わせを総当たりで試す。", "kid": "「これとこれを組み合わせたら一番いい結果になるかな」というのを、思いつく組み合わせぜんぶ、もれなく試してみるやり方。", "eg": "洋服のコーディネートで例えると、上着3種類×ズボン2種類の全部の組み合わせ(6通り)を実際に着て鏡で確かめるようなもの。「なんとなく良さそうな組み合わせ」だけを選ばず、全部試して一番良いものを選ぶ。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">λ3通り × α2通り＝6通りを総当たり</text><text x=\"110\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">λ=0.1</text><text x=\"190\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">λ=1</text><text x=\"270\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">λ=10</text><text x=\"55\" y=\"57\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">α=0.5</text><text x=\"55\" y=\"91\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">α=1</text><rect x=\"75\" y=\"42\" width=\"68\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"109\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">0.1,0.5</text><rect x=\"155\" y=\"42\" width=\"68\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"189\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">1,0.5</text><rect x=\"235\" y=\"42\" width=\"68\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"269\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">10,0.5</text><rect x=\"75\" y=\"76\" width=\"68\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"109\" y=\"94\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">0.1,1</text><rect x=\"155\" y=\"76\" width=\"68\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"189\" y=\"94\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">1,1</text><rect x=\"235\" y=\"76\" width=\"68\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"269\" y=\"94\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">10,1</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">マス目1つ＝1つの組み合わせ</text><text x=\"170\" y=\"136\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">全部で6通り試す</text></svg>", "terms": [["グリッドサーチ", "ハイパーパラメータの候補を格子状(グリッド)に組み合わせ、すべて総当たりで試す方法"], ["ハイパーパラメータ", "正則化の強さのように、学習を始める前に人があらかじめ決めておく設定値"]], "calc": "λの候補   0.1, 1, 10 → 3通り\nαの候補   0.5, 1 → 2通り\n組み合わせ 3 × 2 = 6通り\n\n(0.1,0.5)(0.1,1)(1,0.5)(1,1)(10,0.5)(10,1) の6通り", "think": "なぜ足し算ではなく掛け算になるのかがカギ。λの候補が3通りあるとき、そのそれぞれに対してαの候補2通り全部を組み合わせられる(λ=0.1のときα=0.5とα=1の2通り、λ=1のときも2通り、λ=10のときも2通り)。3つのλそれぞれに2通りずつのαが付くので、3×2=6通りになる。足し算(3+2=5通り)では片方の候補を組み合わせずに数えてしまい、実際に試すべき組み合わせより少なくなってしまう。", "vs": "「λだけ変えて試す」「αだけ変えて試す」という片方ずつの探し方と違い、グリッドサーチは両方を掛け合わせたすべての組み合わせを試す。片方だけでは、もう片方との相性の良い組み合わせを見逃す。", "why_asked": "正則化の強さを1つ決めるだけでも、実際にはリッジかラッソかの選択や、いくつかの追加設定が絡むことが多い。それぞれの組み合わせを漏れなく比べる方法を知らないと、たまたま試した一部の設定だけで「これが一番良い」と勘違いしてしまう。", "usecase": "リッジ回帰・ラッソ回帰の正則化の強さ(λ)を、交差検証の平均スコアが一番良くなるように自動で探すとき、実務で幅広く使われる。", "opt": ["正解。λの3通りそれぞれにαの2通りが組み合わさるので、3×2=6通り。", "3+2=5通りは足し算の結果で、片方の候補ぶんの組み合わせが数えられていない。グリッドサーチは総当たりなので掛け算になる。", "λの候補だけを試すと3通りにしかならず、αとの組み合わせを一切試していない。グリッドサーチは両方を組み合わせて試す方法。", "αの候補だけを試すと2通りにしかならず、λとの組み合わせを一切試していない。グリッドサーチは両方を組み合わせて試す方法。"]}')

) AS v(source_ref, category_name, question_text, code, options,
